<script setup>
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue';
import { CalendarDays, CalendarPlus, ChevronLeft, ChevronRight, Clock3, Target, CircleCheck, Flame, BookOpen, RotateCcw, ClipboardList, Flag, Sparkles, Plus, Pencil, Trash2, Check, X, RefreshCw } from 'lucide-vue-next';
import { useAuthStore } from '~/stores/api/auth';
import { useUserStudyPlanStore } from '~/stores/api/userStudyPlan';
import { canAccessPage } from '~/utils/roles';

definePageMeta({ layout: 'default' });
const auth = useAuthStore();
const store = useUserStudyPlanStore();
const route = useRoute();
const ready = ref(false);
const currentMonth = ref(new Date());
const formOpen = ref(false);
const detail = ref(null);
const editingId = ref(null);
const previewOpen = ref(false);
const availabilityOpen = ref(false);
const materialOptions = ref([]);
const card = 'min-w-0 rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-6';
const input = 'w-full min-w-0 rounded-xl border border-outline-variant bg-surface-container-low px-3 py-2.5 text-sm outline-none focus:border-primary-container';
const typeLabels = { material: 'Materi', practice: 'Latihan Soal', review: 'Review', tryout_recap: 'Rekap Tryout', target: 'Target', milestone: 'Milestone', personal: 'Personal' };
const typeColors = { material: 'bg-blue-100 text-blue-700', practice: 'bg-orange-100 text-orange-700', review: 'bg-purple-100 text-purple-700', tryout_recap: 'bg-emerald-100 text-emerald-700', target: 'bg-blue-100 text-blue-700', milestone: 'bg-rose-100 text-rose-700', personal: 'bg-slate-100 text-slate-700' };
const subtests = ['PU', 'PPU', 'PBM', 'PK', 'LBI', 'LBE', 'PM'];
const dateKey = date => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
const today = () => dateKey(new Date());
const addDays = (day, count) => new Date(Date.parse(`${day}T00:00:00Z`) + count * 86400000).toISOString().slice(0, 10);
const weekStart = day => { const date = new Date(`${day}T00:00:00Z`); return addDays(day, -((date.getUTCDay() + 6) % 7)); };
const selected = computed(() => store.selectedDate || today());
const monthTitle = computed(() => currentMonth.value.toLocaleDateString('id-ID', { month: 'long', year: 'numeric' }));
const gridStart = computed(() => weekStart(`${currentMonth.value.getFullYear()}-${String(currentMonth.value.getMonth() + 1).padStart(2, '0')}-01`));
const gridDays = computed(() => Array.from({ length: 42 }, (_, index) => addDays(gridStart.value, index)));
const visibleDays = computed(() => store.calendarView === 'week' ? Array.from({ length: 7 }, (_, index) => addDays(weekStart(selected.value), index)) : gridDays.value);
const weekDays = computed(() => store.weekSummary?.daily || []);
const selectedAgenda = computed(() => store.dailyAgenda || []);
const selectedCompleted = computed(() => selectedAgenda.value.filter(plan => plan.status === 'completed').length);
const summary = computed(() => [
  { label: 'Jadwal Hari Ini', value: store.plans.filter(plan => dateKey(new Date(plan.start_at)) === today()).length, icon: CalendarDays },
  { label: 'Target Minggu Ini', value: store.weekSummary?.planned ?? 0, icon: Target },
  { label: 'Selesai Minggu Ini', value: store.weekSummary?.completed ?? 0, icon: CircleCheck },
  { label: 'Streak Belajar', value: `${store.recommendations?.streak_days ?? 0} Hari`, icon: Flame },
]);
const defaultForm = () => ({ title: '', type: 'material', date: selected.value, time: '19:00', duration_minutes: 45, subtest: '', material_id: '', target_questions: '', notes: '', repeat_type: 'none', repeat_until: '', reminder_minutes: '', source: 'manual', roadmap_stage: null });
const form = reactive(defaultForm());
const weekdays = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu', 'Minggu'];
const availability = reactive(Object.fromEntries(['monday','tuesday','wednesday','thursday','friday','saturday','sunday'].map((day, i) => [day, i < 5 ? [{ start: '19:00', end: '20:00' }] : []])));
const availabilityKeys = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];
function toggleAvailability(key, enabled) { availability[key] = enabled ? [{ start: '19:00', end: '20:00' }] : []; }
const hour = value => value ? new Date(value).toLocaleTimeString('id-ID', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit' }) : '—';
const readable = value => new Date(`${value}T00:00:00`).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
const status = plan => plan.status === 'completed' ? 'Selesai' : plan.status === 'cancelled' ? 'Dibatalkan' : plan.status === 'in_progress' ? 'Sedang Dikerjakan' : plan.status === 'missed' || (new Date(plan.end_at || plan.start_at) < new Date()) ? 'Terlewat' : 'Belum Mulai';
const eventsOn = day => store.plans.filter(plan => dateKey(new Date(plan.start_at)) === day && (!store.filters.type || plan.type === store.filters.type));

async function refresh() {
  const from = gridStart.value;
  await Promise.all([store.fetchPlans(from, addDays(from, 41)), store.fetchDayAgenda(selected.value), store.fetchWeekSummary(weekStart(selected.value))]);
}
async function chooseDay(day) { store.selectedDate = day; await Promise.all([store.fetchDayAgenda(day), store.fetchWeekSummary(weekStart(day))]); }
async function moveMonth(offset) { currentMonth.value = new Date(currentMonth.value.getFullYear(), currentMonth.value.getMonth() + offset, 1); await refresh(); }
async function goToday() { currentMonth.value = new Date(); await chooseDay(today()); await refresh(); }
function openForm(plan = null) {
  editingId.value = plan?.plan_id || null;
  Object.assign(form, defaultForm());
  if (plan) Object.assign(form, { title: plan.title, type: plan.type, date: dateKey(new Date(plan.start_at)), time: hour(plan.start_at).replace('.', ':'), duration_minutes: plan.duration_minutes || 45, subtest: plan.subtest || '', material_id: plan.material_id || '', target_questions: plan.target_questions || '', notes: plan.notes || '', reminder_minutes: plan.reminder_minutes ?? '', source: plan.source, roadmap_stage: plan.roadmap_stage });
  detail.value = null; formOpen.value = true; loadMaterials();
}
function fromRoadmap() {
  openForm();
  const suggestion = store.recommendations?.suggestions?.[0];
  if (suggestion) Object.assign(form, { title: suggestion.title, type: suggestion.type, subtest: suggestion.subtest || '', duration_minutes: suggestion.duration_minutes, target_questions: suggestion.target_questions || '', source: 'roadmap', roadmap_stage: store.recommendations?.roadmap_stage });
}
async function loadMaterials() {
  if (form.type !== 'material') return;
  try { const result = await store.request('/materials', { query: { subtest: form.subtest } }); materialOptions.value = result.data || []; }
  catch { materialOptions.value = []; }
}
watch(() => [form.type, form.subtest], () => { form.material_id = ''; loadMaterials(); });
async function saveForm() {
  const start = new Date(`${form.date}T${form.time}:00+07:00`);
  const payload = { title: form.title, type: form.type, subtest: form.subtest || null, material_id: form.material_id || null, target_questions: form.target_questions || null, notes: form.notes || null, start_at: start.toISOString(), duration_minutes: Number(form.duration_minutes), repeat_type: editingId.value ? 'none' : form.repeat_type, repeat_until: form.repeat_type !== 'none' && !editingId.value && form.repeat_until ? new Date(`${form.repeat_until}T23:59:59+07:00`).toISOString() : null, reminder_minutes: form.reminder_minutes === '' ? null : Number(form.reminder_minutes), source: form.source, roadmap_stage: form.roadmap_stage };
  const result = editingId.value ? await store.updatePlan(editingId.value, payload) : await store.createPlan(payload);
  if (!result) return;
  formOpen.value = false;
  currentMonth.value = new Date(`${form.date}T00:00:00`);
  await chooseDay(form.date); await refresh();
}
async function complete(plan) { if (await store.completePlan(plan.plan_id)) { detail.value = null; await refresh(); } }
async function remove(plan) { if (!confirm(`Hapus jadwal “${plan.title}”?`)) return; if (await store.deletePlan(plan.plan_id)) { detail.value = null; await refresh(); } }
async function makePreview() { const result = await store.generatePlan({ week_start: weekStart(selected.value), availability }); if (result) { availabilityOpen.value = false; previewOpen.value = true; } }
async function savePreview() { if (await store.saveGeneratedPlan()) { previewOpen.value = false; await refresh(); } }

onMounted(async () => {
  auth.initializeAuth();
  if (!auth.token) return navigateTo('/login');
  const user = await auth.fetchCurrentUser();
  if (Number(user?.role) !== 2 || !canAccessPage(user?.role, 'study-plan.self')) return navigateTo('/dashboard');
  if (user?.is_activate !== true) return navigateTo('/dashboard');
  store.selectedDate = today(); ready.value = true;
  await Promise.all([refresh(), store.fetchRecommendations()]);
  if (route.query.source === 'roadmap') fromRoadmap();
  const requestedMaterial = Number(route.query.material_id);
  if (route.query.type === 'material' && Number.isSafeInteger(requestedMaterial) && requestedMaterial > 0) {
    openForm();
    await loadMaterials();
    const match = materialOptions.value.find(item => item.id === requestedMaterial);
    if (match) {
      form.subtest = match.subtest;
      await nextTick();
      await loadMaterials();
      form.material_id = requestedMaterial;
      form.title = `Pelajari ${match.title}`;
    }
  }
});
</script>

<template>
  <div class="mx-auto w-full max-w-[1600px] min-w-0 px-4 py-5 sm:px-6 sm:py-7 lg:px-8">
    <header class="mb-5 flex flex-wrap items-start justify-between gap-3"><div><div class="mb-2 inline-flex items-center gap-1 rounded-full bg-pale-blue px-3 py-1 text-xs font-semibold text-primary-container"><CalendarDays class="h-3.5 w-3.5" />SNBT {{ store.recommendations?.snbt_year || '—' }}</div><h1 class="text-2xl font-bold text-on-surface sm:text-3xl">Study Plan</h1><p class="mt-1 text-sm text-on-surface-variant">Atur jadwal belajar, target harian, dan milestone menuju SNBT.</p></div><button class="inline-flex items-center gap-2 rounded-2xl bg-primary-container px-4 py-2.5 text-sm font-semibold text-white" @click="openForm()"><CalendarPlus class="h-4 w-4" />Tambah Jadwal</button></header>
    <div v-if="store.error" role="alert" class="mb-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-rose-200 bg-white p-4 text-sm text-rose-700"><span>{{ store.error }}</span><button class="inline-flex items-center gap-1 font-semibold" @click="refresh()"><RefreshCw class="h-4 w-4" />Coba Lagi</button></div>
    <div v-if="!ready || store.isLoading" class="space-y-4" aria-label="Memuat Study Plan"><div class="grid grid-cols-2 gap-3 lg:grid-cols-4"><div v-for="i in 4" :key="i" class="h-24 animate-pulse rounded-3xl bg-slate-200" /></div><div class="grid gap-4 lg:grid-cols-12"><div class="h-[500px] animate-pulse rounded-3xl bg-slate-200 lg:col-span-8" /><div class="h-[500px] animate-pulse rounded-3xl bg-slate-200 lg:col-span-4" /></div></div>
    <template v-else>
      <section class="mb-5 grid grid-cols-2 gap-3 lg:grid-cols-4"><article v-for="item in summary" :key="item.label" :class="card" class="p-4"><div class="mb-3 flex h-9 w-9 items-center justify-center rounded-xl bg-pale-blue text-primary-container"><component :is="item.icon" class="h-5 w-5" /></div><p class="text-xs text-outline">{{ item.label }}</p><strong class="mt-1 block text-xl text-on-surface">{{ item.value }}</strong></article></section>
      <div class="grid min-w-0 items-start gap-4 lg:grid-cols-12"><section :class="card" class="lg:col-span-8"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-lg font-bold capitalize">{{ monthTitle }}</h2><p class="text-xs text-outline">Pilih tanggal untuk melihat agenda.</p></div><div class="flex flex-wrap items-center gap-2"><select v-model="store.filters.type" aria-label="Filter tipe kegiatan" :class="input" class="max-w-32"><option value="">Semua</option><option v-for="(label, key) in typeLabels" :key="key" :value="key">{{ label }}</option></select><button class="rounded-xl border border-soft-blue p-2" aria-label="Bulan sebelumnya" @click="moveMonth(-1)"><ChevronLeft class="h-4 w-4" /></button><button class="rounded-xl border border-soft-blue px-2 py-2 text-xs font-semibold" @click="goToday">Hari Ini</button><button class="rounded-xl border border-soft-blue p-2" aria-label="Bulan berikutnya" @click="moveMonth(1)"><ChevronRight class="h-4 w-4" /></button></div></div><div class="mb-3 flex gap-2"><button v-for="view in ['month','week','agenda']" :key="view" class="rounded-full px-3 py-1.5 text-xs font-semibold" :class="store.calendarView === view ? 'bg-primary-container text-white' : 'bg-surface-container-low text-on-surface-variant'" @click="store.calendarView = view">{{ {month:'Bulan',week:'Minggu',agenda:'Agenda'}[view] }}</button></div>
        <div v-if="store.calendarView !== 'agenda'" class="min-w-0">
          <div class="grid grid-cols-7 gap-1 text-center text-[10px] font-semibold text-outline sm:text-xs"><span v-for="day in ['Sen','Sel','Rab','Kam','Jum','Sab','Min']" :key="day" class="py-2">{{ day }}</span></div>
          <div class="grid grid-cols-7 gap-1">
            <div v-for="day in visibleDays" :key="day" class="min-h-16 min-w-0 overflow-hidden rounded-xl border p-1 text-left sm:min-h-24 sm:p-2" :class="[day === selected ? 'border-blue-600 bg-pale-blue' : 'border-soft-blue', day === today() ? 'ring-1 ring-blue-500' : '', day.slice(0,7) !== dateKey(currentMonth).slice(0,7) && store.calendarView === 'month' ? 'opacity-55' : '']">
              <button class="w-full text-left text-xs font-semibold" :aria-label="`Lihat agenda ${day}`" @click="chooseDay(day)">{{ Number(day.slice(-2)) }}</button>
              <div class="mt-1 hidden space-y-1 sm:block"><button v-for="event in eventsOn(day).slice(0,2)" :key="event.plan_id" class="block w-full truncate rounded px-1 py-0.5 text-left text-[10px]" :class="typeColors[event.type]" @click="detail = event">{{ event.title }}</button><button v-if="eventsOn(day).length > 2" class="text-[10px] text-outline" @click="chooseDay(day)">+{{ eventsOn(day).length - 2 }} lainnya</button></div>
              <button v-if="eventsOn(day).length" class="mt-1 block text-[9px] text-primary-container sm:hidden" @click="chooseDay(day)">{{ eventsOn(day).length }} jadwal</button>
            </div>
          </div>
        </div>
        <div v-else class="space-y-2"><button v-for="plan in store.plans.filter(item => !store.filters.type || item.type === store.filters.type)" :key="plan.plan_id" class="flex w-full items-center justify-between gap-3 rounded-xl border border-soft-blue p-3 text-left text-sm" @click="detail = plan"><span><strong class="block">{{ plan.title }}</strong><small class="text-outline">{{ readable(dateKey(new Date(plan.start_at))) }} · {{ hour(plan.start_at) }}</small></span><span class="text-xs" :class="typeColors[plan.type]">{{ typeLabels[plan.type] }}</span></button><p v-if="!store.plans.length" class="py-8 text-center text-sm text-outline">Belum ada jadwal pada bulan ini.</p></div>
      </section>
      <aside :class="card" class="lg:col-span-4"><div class="flex items-center gap-2"><Clock3 class="h-5 w-5 text-primary-container" /><h2 class="text-lg font-bold">Agenda {{ selected === today() ? 'Hari Ini' : readable(selected) }}</h2></div><p class="mt-1 text-xs text-outline">{{ selectedCompleted }} / {{ selectedAgenda.length }} jadwal selesai</p><div class="mt-3 h-2 rounded-full bg-surface-container"><div class="h-full rounded-full bg-blue-600" :style="{ width: `${selectedAgenda.length ? Math.round(100 * selectedCompleted / selectedAgenda.length) : 0}%` }" /></div><div v-if="!selectedAgenda.length" class="py-9 text-center"><CalendarDays class="mx-auto h-9 w-9 text-primary-container" /><p class="mt-3 text-sm font-semibold">Belum ada jadwal belajar hari ini.</p><p class="mt-1 text-xs text-outline">Mulai susun Study Plan agar target belajarmu lebih terarah.</p><button class="mt-3 text-sm font-semibold text-primary-container" @click="openForm()">Tambah Jadwal</button></div><div v-else class="mt-4 space-y-2"><div v-for="plan in selectedAgenda" :key="plan.plan_id" class="rounded-2xl border border-soft-blue p-3"><div class="flex items-start justify-between gap-2"><span class="text-xs font-bold text-primary-container">{{ hour(plan.start_at) }}</span><span class="rounded-full px-2 py-0.5 text-[10px]" :class="typeColors[plan.type]">{{ typeLabels[plan.type] }}</span></div><button class="mt-1 block w-full text-left text-sm font-semibold" @click="detail = plan">{{ plan.title }}</button><p class="mt-1 text-xs text-outline">{{ plan.duration_minutes || '—' }} menit · {{ status(plan) }}</p><button v-if="plan.status !== 'completed'" class="mt-2 inline-flex items-center gap-1 text-xs font-semibold text-primary-container" @click="complete(plan)"><Check class="h-3.5 w-3.5" />Tandai Selesai</button></div></div></aside></div>

      <div class="mt-4 grid min-w-0 items-start gap-4 lg:grid-cols-12"><div class="min-w-0 space-y-4 lg:col-span-8"><section :class="card"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="text-lg font-bold">Rencana Minggu Ini</h2><p class="text-xs text-outline">{{ store.weekSummary?.completed || 0 }} / {{ store.weekSummary?.planned || 0 }} target selesai · {{ store.weekSummary?.completion_rate || 0 }}%</p></div><button class="inline-flex items-center gap-1 rounded-xl bg-pale-blue px-3 py-2 text-xs font-semibold text-primary-container" @click="availabilityOpen = true"><Sparkles class="h-4 w-4" />Buat Rencana Otomatis</button></div><div class="mt-4 h-2 rounded-full bg-surface-container"><div class="h-full rounded-full bg-blue-600" :style="{ width: `${store.weekSummary?.completion_rate || 0}%` }" /></div><div class="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-7"><button v-for="(day, index) in weekDays" :key="day.date" class="min-w-0 rounded-2xl border border-soft-blue p-3 text-left" @click="chooseDay(day.date)"><strong class="text-xs">{{ weekdays[index] }}</strong><span class="block text-xs text-outline">{{ day.completed }} / {{ day.planned }} selesai</span><span v-for="plan in day.plans.slice(0,2)" :key="plan.plan_id" class="mt-1 block truncate text-[11px]">{{ plan.title }}</span></button></div><p v-if="!store.weekSummary?.planned" class="mt-4 text-sm text-outline">Belum ada jadwal belajar minggu ini. Tambah jadwal atau buat pratinjau rencana otomatis.</p></section>
        <section :class="card"><div class="flex items-center gap-2"><BookOpen class="h-5 w-5 text-primary-container" /><h2 class="text-lg font-bold">Rekomendasi dari Roadmap</h2></div><div v-if="store.recommendations?.focus_subtest"><p class="mt-4 text-xs font-semibold text-primary-container">Fokus Minggu Ini · {{ store.recommendations.focus_subtest }}</p><h3 class="mt-1 font-bold">{{ store.recommendations.focus_name }}</h3><p class="mt-1 text-sm text-on-surface-variant">{{ store.recommendations.description }}</p><div class="mt-3 flex flex-wrap gap-2"><span v-for="suggestion in store.recommendations.suggestions" :key="suggestion.title" class="rounded-full bg-pale-blue px-3 py-1 text-xs text-primary-container">{{ suggestion.title }}</span></div><button class="mt-4 inline-flex items-center gap-1 text-sm font-semibold text-primary-container" @click="fromRoadmap"><Plus class="h-4 w-4" />Tambahkan ke Study Plan</button></div><p v-else class="mt-4 text-sm text-outline">Rekomendasi personal akan tampil setelah materi dan progres tersedia.</p></section></div>
        <aside class="min-w-0 space-y-4 lg:col-span-4"><section :class="card"><div class="flex items-center gap-2"><Flag class="h-5 w-5 text-primary-container" /><h2 class="font-bold">Milestone Terdekat</h2></div><div v-for="milestone in store.recommendations?.milestones || []" :key="milestone.title" class="border-b border-soft-blue py-3 text-sm last:border-0"><p class="font-semibold">{{ milestone.title }}</p><p class="text-xs text-outline">{{ milestone.due_at ? readable(milestone.due_at) : 'Sesuai progres belajar' }}</p></div><p v-if="!store.recommendations?.milestones?.length" class="mt-3 text-sm text-outline">Milestone belum tersedia.</p></section><section :class="card"><div class="flex items-center gap-2"><Target class="h-5 w-5 text-primary-container" /><h2 class="font-bold">Progress Mingguan</h2></div><div class="mt-4 grid grid-cols-2 gap-3 text-sm"><div><p class="text-xs text-outline">Completion Rate</p><strong>{{ store.weekSummary?.completion_rate || 0 }}%</strong></div><div><p class="text-xs text-outline">Waktu Belajar</p><strong>{{ store.weekSummary?.total_minutes || 0 }} / {{ store.weekSummary?.target_minutes || 0 }} menit</strong></div><div><p class="text-xs text-outline">Soal Direncanakan</p><strong>{{ store.weekSummary?.questions_planned || 0 }}</strong></div><div><p class="text-xs text-outline">Target Soal pada Jadwal Selesai</p><strong>{{ store.weekSummary?.questions_completed || 0 }}</strong></div></div><p class="mt-3 text-xs text-outline">Target pada jadwal selesai bukan jumlah soal yang dikerjakan.</p></section></aside></div>
    </template>

    <div v-if="formOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-3" @click.self="formOpen = false"><div role="dialog" aria-modal="true" aria-label="Form jadwal belajar" class="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-3xl bg-white p-5 shadow-2xl sm:p-6"><div class="mb-4 flex items-center justify-between"><h2 class="text-lg font-bold">{{ editingId ? 'Edit Jadwal' : 'Tambah Jadwal' }}</h2><button aria-label="Tutup" @click="formOpen = false"><X class="h-5 w-5" /></button></div><form class="grid gap-3 sm:grid-cols-2" @submit.prevent="saveForm"><label class="sm:col-span-2"><span class="mb-1 block text-xs font-semibold">Judul *</span><input v-model="form.title" :class="input" maxlength="200" required /></label><label><span class="mb-1 block text-xs font-semibold">Tipe Aktivitas *</span><select v-model="form.type" :class="input"><option v-for="(label,key) in typeLabels" :key="key" :value="key">{{ label }}</option></select></label><label><span class="mb-1 block text-xs font-semibold">Tanggal *</span><input v-model="form.date" type="date" :class="input" required /></label><label><span class="mb-1 block text-xs font-semibold">Jam Mulai *</span><input v-model="form.time" type="time" :class="input" required /></label><label><span class="mb-1 block text-xs font-semibold">Durasi (menit)</span><input v-model.number="form.duration_minutes" type="number" min="1" max="1440" :class="input" /></label><label v-if="['material','practice','review'].includes(form.type)"><span class="mb-1 block text-xs font-semibold">Subtes</span><select v-model="form.subtest" :class="input"><option value="">Pilih subtes</option><option v-for="code in subtests" :key="code">{{ code }}</option></select></label><label v-if="form.type === 'material'"><span class="mb-1 block text-xs font-semibold">Materi aktif</span><select v-model="form.material_id" :class="input"><option value="">Tanpa materi spesifik</option><option v-for="item in materialOptions" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label v-if="form.type === 'practice'"><span class="mb-1 block text-xs font-semibold">Target jumlah soal</span><input v-model.number="form.target_questions" type="number" min="1" max="10000" :class="input" /></label><label v-if="!editingId"><span class="mb-1 block text-xs font-semibold">Ulangi</span><select v-model="form.repeat_type" :class="input"><option value="none">Tidak berulang</option><option value="daily">Setiap hari</option><option value="weekly">Setiap minggu</option></select></label><label v-if="form.repeat_type !== 'none' && !editingId"><span class="mb-1 block text-xs font-semibold">Ulangi sampai</span><input v-model="form.repeat_until" type="date" :min="form.date" :class="input" required /></label><label><span class="mb-1 block text-xs font-semibold">Pengingat di aplikasi</span><select v-model="form.reminder_minutes" :class="input"><option value="">Tidak ada</option><option :value="10">10 menit sebelumnya</option><option :value="30">30 menit sebelumnya</option><option :value="60">1 jam sebelumnya</option><option :value="1440">1 hari sebelumnya</option></select></label><p v-if="form.type === 'tryout_recap'" class="rounded-xl bg-emerald-50 p-3 text-xs text-emerald-800 sm:col-span-2">Jadwalkan evaluasi hasil tryout dari platform eksternal. <NuxtLink to="/tryout-recap/create" class="font-semibold underline">Tambahkan Rekap Tryout</NuxtLink></p><label class="sm:col-span-2"><span class="mb-1 block text-xs font-semibold">Catatan</span><textarea v-model="form.notes" rows="3" :class="input" maxlength="4000" /></label><p v-if="store.error" role="alert" class="text-sm text-rose-700 sm:col-span-2">{{ store.error }}</p><div class="flex justify-end gap-2 sm:col-span-2"><button type="button" class="rounded-xl border border-soft-blue px-4 py-2 text-sm" @click="formOpen = false">Batal</button><button type="submit" :disabled="store.isSaving" class="rounded-xl bg-primary-container px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">Simpan Jadwal</button></div></form></div></div>
    <div v-if="detail" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-3" @click.self="detail = null"><div role="dialog" aria-modal="true" aria-label="Detail jadwal" class="w-full max-w-md rounded-3xl bg-white p-5 shadow-2xl"><div class="flex justify-between gap-3"><span class="rounded-full px-3 py-1 text-xs" :class="typeColors[detail.type]">{{ typeLabels[detail.type] }}</span><button aria-label="Tutup" @click="detail = null"><X class="h-5 w-5" /></button></div><h2 class="mt-4 text-xl font-bold">{{ detail.title }}</h2><p class="mt-2 text-sm text-on-surface-variant">{{ readable(dateKey(new Date(detail.start_at))) }} · {{ hour(detail.start_at) }} · {{ detail.duration_minutes || '—' }} menit</p><p class="mt-2 text-sm">Status: {{ status(detail) }}</p><p v-if="detail.subtest" class="mt-1 text-sm">Subtes: {{ detail.subtest }}</p><p v-if="detail.target_questions" class="mt-1 text-sm">Target: {{ detail.target_questions }} soal</p><p v-if="detail.reminder_minutes != null" class="mt-1 text-sm">Pengingat di kalender: {{ detail.reminder_minutes === 0 ? "Saat mulai" : `${detail.reminder_minutes} menit sebelumnya` }}</p><p v-if="detail.notes" class="mt-3 rounded-xl bg-surface-container-low p-3 text-sm">{{ detail.notes }}</p><div class="mt-5 flex flex-wrap gap-2"><button v-if="detail.status !== 'completed'" class="inline-flex items-center gap-1 rounded-xl bg-primary-container px-3 py-2 text-xs font-semibold text-white" @click="complete(detail)"><Check class="h-4 w-4" />Selesai</button><button v-if="detail.status !== 'completed'" class="inline-flex items-center gap-1 rounded-xl border border-soft-blue px-3 py-2 text-xs" @click="openForm(detail)"><Pencil class="h-4 w-4" />Edit</button><button class="inline-flex items-center gap-1 rounded-xl border border-rose-200 px-3 py-2 text-xs text-rose-700" @click="remove(detail)"><Trash2 class="h-4 w-4" />Hapus</button></div></div></div>
    <div v-if="availabilityOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-3" @click.self="availabilityOpen = false"><div role="dialog" aria-modal="true" aria-label="Atur waktu belajar" class="max-h-[88vh] w-full max-w-md overflow-y-auto rounded-3xl bg-white p-5 shadow-2xl"><div class="flex justify-between gap-3"><div><h2 class="text-lg font-bold">Atur Waktu Belajar</h2><p class="text-xs text-outline">Pilih hari dan jam yang tersedia minggu ini.</p></div><button aria-label="Tutup" @click="availabilityOpen = false"><X class="h-5 w-5" /></button></div><div class="mt-4 space-y-2"><div v-for="(key,index) in availabilityKeys" :key="key" class="grid grid-cols-[1fr_auto_auto] items-center gap-2 rounded-xl border border-soft-blue p-2 text-sm"><label class="flex items-center gap-2"><input type="checkbox" :checked="availability[key].length > 0" @change="toggleAvailability(key, $event.target.checked)" />{{ weekdays[index] }}</label><input v-if="availability[key].length" v-model="availability[key][0].start" type="time" class="min-w-0 rounded-lg border border-soft-blue p-1 text-xs" :aria-label="`Mulai ${weekdays[index]}`" /><input v-if="availability[key].length" v-model="availability[key][0].end" type="time" class="min-w-0 rounded-lg border border-soft-blue p-1 text-xs" :aria-label="`Selesai ${weekdays[index]}`" /></div></div><p v-if="store.error" class="mt-3 text-sm text-rose-700">{{ store.error }}</p><div class="mt-5 flex justify-end gap-2"><button class="rounded-xl border border-soft-blue px-4 py-2 text-sm" @click="availabilityOpen = false">Batal</button><button :disabled="store.isGenerating" class="rounded-xl bg-primary-container px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="makePreview">Lihat Pratinjau</button></div></div></div>
    <div v-if="previewOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-3" @click.self="previewOpen = false"><div role="dialog" aria-modal="true" aria-label="Pratinjau rencana otomatis" class="max-h-[88vh] w-full max-w-lg overflow-y-auto rounded-3xl bg-white p-5 shadow-2xl"><div class="flex justify-between gap-3"><div><h2 class="text-lg font-bold">Pratinjau Rencana Mingguan</h2><p class="text-xs text-outline">Belum disimpan. Tinjau jadwal sebelum menambahkannya.</p></div><button aria-label="Tutup" @click="previewOpen = false"><X class="h-5 w-5" /></button></div><p v-if="store.generatedPlan?.skipped_conflicts" class="mt-3 text-xs text-amber-700">{{ store.generatedPlan.skipped_conflicts }} slot dilewati karena bertabrakan dengan jadwal.</p><div v-for="plan in store.generatedPlan?.plans || []" :key="plan.start_at" class="mt-3 rounded-2xl border border-soft-blue p-3"><strong class="text-sm">{{ plan.title }}</strong><p class="text-xs text-outline">{{ readable(dateKey(new Date(plan.start_at))) }} · {{ hour(plan.start_at) }} · {{ plan.duration_minutes }} menit</p></div><p v-if="!store.generatedPlan?.plans?.length" class="mt-4 text-sm text-outline">Belum ada slot kosong. Ubah waktu belajar atau jadwal yang sudah ada.</p><p v-if="store.error" class="mt-3 text-sm text-rose-700">{{ store.error }}</p><div class="mt-5 flex justify-end gap-2"><button class="rounded-xl border border-soft-blue px-4 py-2 text-sm" @click="previewOpen = false">Batal</button><button :disabled="!store.generatedPlan?.plans?.length || store.isSaving" class="rounded-xl bg-primary-container px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="savePreview">Simpan Rencana</button></div></div></div>
  </div>
</template>

